package com.nook.service; import com.nook.domain.SocialEntities.CoffeeShop; import com.nook.dto.ApiDtos.*; import com.nook.exception.ApiException; import com.nook.mapper.SocialMapper; import com.nook.repository.SocialRepository; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*; @Service public class CoffeeShopService {final PlacesProvider provider;final SocialMapper mapper;final SocialRepository repo;public CoffeeShopService(PlacesProvider p,SocialMapper m,SocialRepository r){provider=p;mapper=m;repo=r;}public List<ShopDto> nearby(double lat,double lng,double radius){return provider.nearby(lat,lng,radius).stream().map(s->mapper.shop(s,lat,lng)).filter(s->s.distanceKm()<=radius).sorted(Comparator.comparingDouble(ShopDto::distanceKm)).toList();}public ShopDto one(UUID id,double lat,double lng){CoffeeShop s=repo.find(CoffeeShop.class,id);if(s==null)throw new ApiException(HttpStatus.NOT_FOUND,"SHOP_NOT_FOUND","Cafetería no encontrada");return mapper.shop(s,lat,lng);} }
